module {tt.func public @narrow(%state:!tt.ptr<f16>,%value:!tt.ptr<f16>,%out:!tt.ptr<f16>) {
      %v=tt.load %value:!tt.ptr<f16>
      %old=tt.atomic_rmw exch, relaxed, gpu, %state, %v:(!tt.ptr<f16>,f16)->f16
      tt.store %out,%old:!tt.ptr<f16>
      tt.return
    }}

