module {tt.func public @typed_print(%x:!tt.ptr<i8>,%out:!tt.ptr<i8>) {
   %loaded=tt.load %x:!tt.ptr<i8>
   %v=arith.trunci %loaded:i8 to i4
   tt.print "value " {hex=false,isSigned=array<i32:1>} : %v:i4
   tt.store %out,%loaded:!tt.ptr<i8>
   tt.return
  }}

